        @(posedge clk);
        if (shift_ena !== 1'b0) begin
            errors = errors + 1;
            $display("Error: Post-4-cycle check 2, expected shift_ena = 0, got %b", shift_ena);
        end

        // Test 2: Apply reset asynchronously/synchronously mid-way and verify it restarts the 4-cycle count
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error: Mid-run reset cycle 1, expected shift_ena = 1, got %b", shift_ena);
        end

        reset = 0;
        @(posedge clk);
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error: Mid-run reset cycle 2, expected shift_ena = 1, got %b", shift_ena);
        end
        @(posedge clk);
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error: Mid-run reset cycle 3, expected shift_ena = 1, got %b", shift_ena);
        end
        @(posedge clk);
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
            $display("Error: Mid-run reset cycle 4, expected shift_ena = 1, got %b", shift_ena);
        end
        @(posedge clk);
        if (shift_ena !== 1'b0) begin
            errors = errors + 1;
            $display("Error: Mid-run post-4-cycle check, expected shift_ena = 0, got %b", shift_ena);
        end

        // Final result reporting
        #20;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
